package com.ruoyi.medical.persistence;
import com.ruoyi.medical.contracts.*;
import java.util.*;
import org.junit.jupiter.api.*;
import static org.junit.jupiter.api.Assertions.*;
import static com.ruoyi.medical.persistence.FormalInputFixture.*;
final class FormalEvaluationInputRegistryTest {
 FormalInputFixture f;String artifact;
 @BeforeEach void setup()throws Exception{f=new FormalInputFixture();artifact=f.register().path("artifact").path("version_id").asText();}
 @AfterEach void cleanup()throws Exception{if(f!=null)f.close();}
 static <T>T changed(T record,String name,Object value)throws Exception{var parts=record.getClass().getRecordComponents();var values=new Object[parts.length];var types=new Class<?>[parts.length];for(int i=0;i<parts.length;i++){types[i]=parts[i].getType();values[i]=parts[i].getName().equals(name)?value:parts[i].getAccessor().invoke(record);}return (T)record.getClass().getDeclaredConstructor(types).newInstance(values);}
 ArtifactRegistryProtocol.ReadRequirement required(){return new ArtifactRegistryProtocol.ReadRequirement(new PermissionProtocol.Scope(TENANT,null,"SOURCE",SOURCE_ID),"source.read",PURPOSE,FormalEvaluationInputSchema.REF,f.input.schemaSha256(),f.input.schemaSha256(),FormalEvaluationInputService.LIMITS);}
 @Test void exactTrustedLocalDescriptorUsesActualSchemaBytesAndOriginalRegistryChecks()throws Exception{var proof=f.transaction(()->f.registry.requireRegistration(f.admission,artifact,required()));assertEquals(FormalEvaluationInputSchema.ARTIFACT_KIND,proof.artifact().artifactKind());assertEquals(Set.of(artifact,SOURCE),proof.lineage().versions().keySet());}
 @Test void wrongKindCannotBorrowFormalSchema()throws Exception{for(String kind:List.of("SIMULATION_INPUT","SAMPLE_MANIFEST","MODEL_RESULT","DOCUMENT_BODY"))assertThrows(TenantAccessException.class,()->ArtifactRegistry.requireLocalFormalInputSchema(changed(f.artifactRows.get(artifact),"artifactKind",kind),required()));}
 @Test void wrongSchemaDigestAndManifestCannotBorrowFormalRef()throws Exception{for(String field:List.of("schemaDocumentSha256","artifactSchemaManifest"))assertThrows(TenantAccessException.class,()->ArtifactRegistry.requireLocalFormalInputSchema(f.artifactRows.get(artifact),changed(required(),field,hash("untrusted schema"))));}
 @Test void otherDefinitionAndVersionDoNotMatchTrustedLocalDescriptor()throws Exception{for(String ref:List.of("urn:medical:formal-evaluation-input:1.0.0#/$defs/Receipt","urn:medical:formal-evaluation-input:2.0.0#/$defs/Document","urn:medical:simulation-input:1.0.0#/$defs/Document"))assertFalse(ArtifactRegistry.requireLocalFormalInputSchema(f.artifactRows.get(artifact),changed(required(),"schemaRef",ref)));}
 @Test void projectAndWrongResourceCannotUseEnterpriseOnlyDescriptor()throws Exception{assertThrows(TenantAccessException.class,()->ArtifactRegistry.requireLocalFormalInputSchema(changed(f.artifactRows.get(artifact),"projectId",id(55)),required()));for(var scope:List.of(new PermissionProtocol.Scope(TENANT,id(55),"SOURCE",SOURCE_ID),new PermissionProtocol.Scope(TENANT,null,"CONFIGURATION",SOURCE_ID)))assertThrows(TenantAccessException.class,()->ArtifactRegistry.requireLocalFormalInputSchema(f.artifactRows.get(artifact),changed(required(),"scope",scope)));}
 @Test void descriptorDoesNotAuthorizeWriteOrMissingPurpose()throws Exception{for(String action:List.of("artifact.register","source.write","configuration.read"))assertThrows(TenantAccessException.class,()->ArtifactRegistry.requireLocalFormalInputSchema(f.artifactRows.get(artifact),changed(required(),"action",action)));for(String purpose:Arrays.asList(null,"","document_body","DOCUMENT BODY","A".repeat(65)))assertThrows(TenantAccessException.class,()->ArtifactRegistry.requireLocalFormalInputSchema(f.artifactRows.get(artifact),changed(required(),"purpose",purpose)));}
 @Test void rehashedBindingSchemaStillFailsTrustedDescriptor()throws Exception{var binding=f.bindings.get(artifact);f.bindings.put(artifact,changed(binding,"schemaDocumentSha256",hash("rehashed")));assertThrows(TenantAccessException.class,()->f.transaction(()->f.registry.requireRegistration(f.admission,artifact,required())));}
 @Test void removedManifestMemberCannotBeHiddenByValidSchema()throws Exception{f.members.get(f.artifactRows.get(artifact).accessSetId()).clear();assertThrows(TenantAccessException.class,()->f.transaction(()->f.registry.requireRegistration(f.admission,artifact,required())));}
 @Test void rootAncestorSourceCannotBeDroppedFromActualLineage()throws Exception{f.parents.get(artifact).clear();assertThrows(TenantAccessException.class,()->f.transaction(()->f.registry.requireRegistration(f.admission,artifact,required())));}
 @Test void localDescriptorNeverBypassesCurrentArtifactOrPrimarySourceGrants(){f.allowed.set(false);assertThrows(TenantAccessException.class,()->f.transaction(()->f.registry.requireRegistration(f.admission,artifact,required())));}
}
